// Some portions generated by Codex
package org.eclipse.rdf4j.sail.lmdb;

import static org.junit.jupiter.api.Assertions.assertArrayEquals;
import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.junit.jupiter.api.Assertions.assertNull;
import static org.junit.jupiter.api.Assertions.assertTrue;

import org.eclipse.rdf4j.query.algebra.evaluation.optimizer.cost.FrontierStateArena;
import org.junit.jupiter.api.Test;

class LmdbFrontierStatementProbeMemoTest {

	@Test
	void retainsExactTuplePairsAndSourceScanCount() {
		try (FrontierStateArena arena = new FrontierStateArena(1L << 20);
				LmdbFrontierStatementProbeMemo memo = LmdbFrontierStatementProbeMemo.createIfCapacity(arena)) {
			assertNotNull(memo);
			LmdbFrontierStatementProbeMemo.Capture capture = memo.beginCapture();
			assertNotNull(capture);
			assertTrue(capture.add(11L, 12L, 13L, 14L));
			assertTrue(capture.add(21L, 22L, 23L, 24L));
			assertTrue(memo.complete(1L, 2L, 3L, 4L, 5, 7L, capture));

			LmdbFrontierStatementProbeMemo.Result result = memo.get(1L, 2L, 3L, 4L, 5);
			assertNotNull(result);
			assertEquals(7L, result.sourceRowsScanned());
			assertEquals(2, result.rowCount());
			assertArrayEquals(new long[] { 11L, 12L, 13L, 14L, 21L, 22L, 23L, 24L }, result.copyQuads());
			assertNull(memo.get(1L, 2L, 3L, 4L, 6), "scope/equality flags are part of the exact key");
		}
	}

	@Test
	void declinesIncompleteCaptureWithoutPublishingPartialResult() {
		try (FrontierStateArena arena = new FrontierStateArena(4_096L);
				LmdbFrontierStatementProbeMemo memo = LmdbFrontierStatementProbeMemo.createIfCapacity(arena)) {
			assertNotNull(memo);
			LmdbFrontierStatementProbeMemo.Capture capture = memo.beginCapture();
			assertNotNull(capture);
			while (capture.add(1L, 2L, 3L, 4L)) {
				// Grow until the shared Frontier memory budget declines the next exact buffer.
			}
			assertTrue(!memo.complete(8L, 9L, 10L, 11L, 12, 13L, capture));
			assertNull(memo.get(8L, 9L, 10L, 11L, 12));
		}
	}

	@Test
	void retainsCompleteProbeKeysAcrossTableGrowth() {
		try (FrontierStateArena arena = new FrontierStateArena(1L << 20);
				LmdbFrontierStatementProbeMemo memo = LmdbFrontierStatementProbeMemo.createIfCapacity(arena)) {
			assertNotNull(memo);
			for (long subject = 1L; subject <= 40L; subject++) {
				LmdbFrontierStatementProbeMemo.Capture capture = memo.beginCapture();
				assertNotNull(capture);
				assertTrue(capture.add(subject + 100L, 12L, 13L, 14L));
				assertTrue(memo.complete(subject, 2L, 3L, 4L, Math.toIntExact(subject), 1L, capture));
			}

			for (long subject = 1L; subject <= 40L; subject++) {
				LmdbFrontierStatementProbeMemo.Result result = memo.get(
						subject, 2L, 3L, 4L, Math.toIntExact(subject));
				assertNotNull(result);
				assertEquals(subject + 100L, result.quad(0, 0));
				assertNull(memo.get(subject, 2L, 3L, 4L, Math.toIntExact(subject + 1L)),
						"probe flags remain part of the complete memo key");
			}
		}
	}
}
